:root {
  --bg: #0f172a;
  --card-bg: #1e293b;
  --key-bg: #334155;
  --key-hover: #475569;
  --key-active: #64748b;
  --accent: #38bdf8;
  --text: #f1f5f9;
  --danger: #f87171;
  --success: #4ade80;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  border: 2px solid var(--key-bg);
}

h1 {
  font-size: 1.6rem;
  text-align: center;
  margin-bottom: 1.5rem;
  letter-spacing: 0.05em;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0c4a6e;
}

.display {
  background: #0f172a;
  border: 3px solid var(--key-bg);
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
  font-size: 1.8rem;
  font-family: 'Courier New', monospace;
  letter-spacing: 0.3em;
  min-height: 4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.75rem;
  color: var(--accent);
}

.status {
  text-align: center;
  min-height: 1.8rem;
  margin-bottom: 1rem;
  font-weight: 600;
  font-size: 1.1rem;
}

.status.success { color: var(--success); }
.status.error { color: var(--danger); }
.status.locked { color: var(--danger); }

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.key {
  background: var(--key-bg);
  color: var(--text);
  border: 2px solid var(--key-hover);
  border-radius: 0.75rem;
  padding: 1rem 0;
  font-size: 1.4rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  box-shadow: 0 4px 0 #1e293b;
  min-height: 3.5rem;
}

.key:hover {
  background: var(--key-hover);
}

.key:active {
  background: var(--key-active);
  transform: translateY(2px);
  box-shadow: 0 2px 0 #1e293b;
}

.key:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.key:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

.clear {
  background: #7f1d1d;
  border-color: #991b1b;
}
.clear:hover { background: #991b1b; }
.clear:active { background: #b91c1c; }

.enter {
  background: #14532d;
  border-color: #166534;
}
.enter:hover { background: #166534; }
.enter:active { background: #15803d; }

[hidden] { display: none !important; }

@media (max-width: 360px) {
  body { padding: 0.5rem; }
  .card { padding: 1.25rem 1rem; }
  h1 { font-size: 1.3rem; }
  .display { font-size: 1.4rem; min-height: 3.2rem; }
  .key { font-size: 1.2rem; padding: 0.8rem 0; min-height: 3rem; }
  .keypad { gap: 0.5rem; }
}

const CORRECT_CODE = '4271';
const MAX_WRONG = 3;
const LOCK_SECONDS = 10;

const displayEl = document.getElementById('display');
const statusEl = document.getElementById('status');
const keypadEl = document.getElementById('keypad');
const clearBtn = document.getElementById('clear');
const enterBtn = document.getElementById('enter');

let entry = '';
let wrongCount = 0;
let locked = false;
let lockTimer = null;

function updateDisplay() {
  displayEl.textContent = entry.padEnd(4, '·');
}

function setStatus(msg, type) {
  statusEl.textContent = msg;
  statusEl.className = 'status' + (type ? ' ' + type : '');
}

function disableKeypad(disabled) {
  const keys = keypadEl.querySelectorAll('button');
  keys.forEach(k => k.disabled = disabled);
}

function startLockout() {
  locked = true;
  disableKeypad(true);
  let remaining = LOCK_SECONDS;
  setStatus(`Locked for ${remaining}s`, 'locked');
  lockTimer = setInterval(() => {
    remaining--;
    if (remaining > 0) {
      setStatus(`Locked for ${remaining}s`, 'locked');
    } else {
      clearInterval(lockTimer);
      lockTimer = null;
      locked = false;
      wrongCount = 0;
      disableKeypad(false);
      setStatus('', '');
      entry = '';
      updateDisplay();
    }
  }, 1000);
}

function handleDigit(digit) {
  if (locked) return;
  if (entry.length < 4) {
    entry += digit;
    updateDisplay();
  }
}

function handleClear() {
  if (locked) return;
  entry = '';
  setStatus('', '');
  updateDisplay();
}

function handleEnter() {
  if (locked) return;
  if (entry.length !== 4) {
    setStatus('Enter 4 digits', 'error');
    return;
  }
  if (entry === CORRECT_CODE) {
    setStatus('Unlocked', 'success');
    entry = '';
    wrongCount = 0;
    updateDisplay();
  } else {
    wrongCount++;
    entry = '';
    updateDisplay();
    if (wrongCount >= MAX_WRONG) {
      setStatus('Wrong code', 'error');
      startLockout();
    } else {
      setStatus('Wrong code', 'error');
    }
  }
}

keypadEl.addEventListener('click', (e) => {
  const btn = e.target.closest('button');
  if (!btn || btn.disabled) return;
  const digit = btn.dataset.digit;
  if (digit !== undefined) {
    handleDigit(digit);
  } else if (btn.id === 'clear') {
    handleClear();
  } else if (btn.id === 'enter') {
    handleEnter();
  }
});

clearBtn.addEventListener('click', handleClear);
enterBtn.addEventListener('click', handleEnter);

updateDisplay();
